/**
 * The command GRAMMAR acpx registers with commander, as data (brick b479441f, C1.2).
 *
 * Why it exists: the placement step must find a command's path BEFORE acpx loads commander's
 * registration and its handlers — that graph costs ~0.5 s per invocation (measured, see the brick's
 * CLASS-TABLE.md) and is exactly what "route before loading the world" forbids (CONCEPTION r4 §12).
 * So `classifyArgv` walks this table instead of commander.
 *
 * ⚠️ DO NOT EDIT BY HAND AS A GUESS. It must equal what commander registers — every path, every
 * alias, every value-taking flag. `test/pod-command-classes.test.ts` derives the same object from the
 * real registration and deep-compares; on a mismatch its message prints the expected object to paste.
 * A flag missing here makes `classifyArgv` read the flag's VALUE as a subcommand or an operand.
 *
 * Keys: `""` is the program (its value flags are the global flags of `addGlobalFlags`); `"<agent>"`
 * is the per-agent command `acpx <agent> …` (`registerAgentCommand`) and lists which top-level paths
 * exist beneath it; every other key is a space-joined command path.
 */
export type GrammarNode = {
  readonly aliases?: readonly string[];
  readonly valueFlags: readonly string[];
  readonly children?: readonly string[];
};

